const COMMON_ARCHETYPES = ["Hero", "Villain", "Trickster", "Mentor", "Guardian", "Wanderer", "Ruler", "Rebel", "Sage", "Innocent"] as const;

const ABILITY_TAGS = [
  "Extra Action", "Resource Gain", "Resource Drain", "Damage Boost",
  "Defense Bonus", "Movement", "Card Draw", "Reroll", "Bypass Rule", "Summon",
] as const;
type AbilityTag = typeof ABILITY_TAGS[number];

function parseResourceScore(resources: string): number {
  const nums = resources.match(/\d+/g);
  return nums ? nums.reduce((s, n) => s + parseInt(n, 10), 0) : 0;
}

function extractResourceNames(resources: string): string[] {
  return resources.split(",").flatMap((part) => {
    const m = part.trim().match(/^\d+\s+(.+)$/);
    return m ? [m[1].trim().toLowerCase()] : [];
  });
