// ─── Resource Progression Editor ──────────────────────────────────────────────

interface ResourceProgressionEditorProps {
  startingResources: string;
  progression: Array<{ turn: number; delta: string }>;
  onChange: (p: Array<{ turn: number; delta: string }>) => void;
}

function ResourceProgressionEditor({ startingResources, progression, onChange }: ResourceProgressionEditorProps) {
  const [open, setOpen] = useState(progression.length > 0);

  useEffect(() => {
    if (progression.length > 0) setOpen(true);
  }, [progression.length]);

  const addTurn = () => {
    const nextTurn = progression.length > 0 ? Math.max(...progression.map((r) => r.turn)) + 1 : 2;
    onChange([...progression, { turn: nextTurn, delta: "" }]);
    setOpen(true);
  };

  const update = (idx: number, field: "turn" | "delta", val: string | number) => {
    const next = [...progression];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };

  const remove = (idx: number) => {
    const next = progression.filter((_, i) => i !== idx);
    onChange(next);
    if (next.length === 0) setOpen(false);
  };

  return (
    <div className="mt-2 space-y-1.5">
      <div className="flex items-center gap-2">
        <button
          onClick={() => setOpen((v) => !v)}
          className="flex items-center gap-1 text-[10px] text-muted-foreground hover:text-foreground transition-colors"
        >
          {open ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
          Resource Progression
          {progression.length > 0 && (
            <span className="ml-1 px-1.5 py-0.5 rounded-full bg-primary/15 text-primary text-[9px] font-medium">
              {progression.length} {progression.length === 1 ? "turn" : "turns"}
            </span>
          )}
        </button>
        <button
          onClick={addTurn}
          className="ml-auto flex items-center gap-0.5 text-[10px] text-muted-foreground hover:text-primary transition-colors"
        >
          <Plus className="h-3 w-3" /> Add Turn
        </button>
      </div>

      {open && (
        <div className="rounded-lg border border-border bg-muted/20 overflow-hidden text-xs">
          {startingResources && (
            <div className="grid grid-cols-[60px_1fr] px-2.5 py-1.5 border-b border-border/50 bg-muted/30">
              <span className="text-muted-foreground font-medium">Turn 1</span>
              <span className="text-foreground/70 truncate">{startingResources}</span>
            </div>
          )}
          {!startingResources && progression.length === 0 && (
            <p className="px-2.5 py-2 text-[10px] text-muted-foreground italic">
              Fill in Starting Resources above, then add turn progressions here.
            </p>
          )}
          {progression.map((row, idx) => (
            <div key={idx} className="grid grid-cols-[60px_1fr_20px] items-center gap-1.5 px-2.5 py-1.5 border-b border-border/30 last:border-0">
              <input
                type="number"
                min={2}
                value={row.turn}
                onChange={(e) => update(idx, "turn", parseInt(e.target.value, 10) || 2)}
                className="w-full h-6 text-xs bg-background/60 border border-border rounded px-1.5 text-center"
                aria-label="Turn number"
              />
              <input
                value={row.delta}
                onChange={(e) => update(idx, "delta", e.target.value)}
                placeholder="e.g. +2 gold, -1 health…"
                className="w-full h-6 text-xs bg-background/60 border border-border rounded px-2 placeholder:text-muted-foreground/50"
                aria-label="Resource changes"
              />
              <button onClick={() => remove(idx)} className="text-muted-foreground hover:text-destructive transition-colors">
                <X className="h-3 w-3" />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

