22	export function ComplexityScore({ projectId, playtestCount }: ComplexityScoreProps) {
23	  const compute = useComputeComplexity();
24	  const mutate = compute.mutate;
25	
26	  useEffect(() => {
27	    mutate({ projectId });
28	  }, [projectId, mutate]);
29	
30	  if (compute.isPending || !compute.data) {
31	    return (
32	      <Card>
33	        <CardHeader className="py-3 px-4 border-b border-border">
34	          <CardTitle className="text-sm font-semibold flex items-center gap-2">
