36	          </CardTitle>
37	        </CardHeader>
38	        <CardContent className="px-4 py-6">
39	          <p className="text-xs text-muted-foreground text-center italic">
40	            {compute.isError ? "Could not compute complexity." : "Computing complexity score…"}
41	          </p>
42	        </CardContent>
43	      </Card>
44	    );
45	  }
46	
47	  // Server returns score on a 0-100 scale; map to 1-5 tier.
48	  const overall100 = compute.data.score;
49	  const overall = Math.max(1, Math.min(5, 1 + (overall100 / 100) * 4));
50	  const tier  = Math.round(overall);
51	  const label = LABELS[tier]  ?? "—";
52	  const color = COLORS[tier]  ?? "text-white";
53	  const refs  = REFS[tier]    ?? "";
54	  const pct   = Math.round(((overall - 1) / 4) * 100);
55	
56	  return (
57	    <Card className="bg-card border-border">
58	      <CardHeader className="pb-3">
59	        <CardTitle className="flex items-center gap-2 text-base">
60	          <BarChart3 className="h-4 w-4 text-primary" /> Design Complexity
61	        </CardTitle>
62	      </CardHeader>
63	      <CardContent className="space-y-4">
64	        <div className="flex items-end justify-between gap-3">
65	          <div>
66	            <p className={`text-3xl font-bold tabular-nums ${color}`}>{overall.toFixed(1)}</p>
67	            <p className={`text-sm font-semibold ${color}`}>{label}</p>
68	          </div>
69	          <p className="text-[10px] text-muted-foreground text-right leading-relaxed max-w-[150px]">
