75	        <div>
76	          <div className="h-2 w-full rounded-full overflow-hidden bg-gradient-to-r from-emerald-900 via-yellow-900 to-red-900">
77	            <div
78	              className="h-full rounded-full bg-white/30 transition-all duration-700"
79	              style={{ width: `${pct}%` }}
80	            />
81	          </div>
