83	            <span>Light</span><span>Medium</span><span>Heavy</span>
84	          </div>
85	        </div>
86	
87	        <div className="space-y-2">
88	          {compute.data.breakdown.map(b => {
89	            const factorScore = Math.max(1, Math.min(5, Math.round(1 + (b.value / 100) * 4)));
90	            return (
91	              <div key={b.factor} className="flex items-center gap-2">
92	                <span className="text-xs text-muted-foreground w-24 shrink-0 capitalize">{b.factor}</span>
93	                <div className="flex gap-0.5 shrink-0">
94	                  {[1, 2, 3, 4, 5].map(n => (
95	                    <span
96	                      key={n}
97	                      className={`h-1.5 w-5 rounded-sm transition-colors ${n <= factorScore ? "bg-primary" : "bg-border"}`}
98	                    />
99	                  ))}
100	                </div>
101	                <span className="text-[10px] text-muted-foreground truncate">{b.value.toFixed(0)}</span>
102	              </div>
103	            );
104	          })}
105	        </div>
106	
107	        {playtestCount !== undefined && playtestCount > 0 && (
108	          <p className="text-[10px] text-emerald-400/80">
109	            ✓ {playtestCount} playtest session{playtestCount !== 1 ? "s" : ""} logged
110	          </p>
111	        )}
112	
113	        <p className="text-[10px] text-muted-foreground/60 italic">
114	          Server-computed estimate based on your project's rules, components, and player range.
115	        </p>
116	      </CardContent>
117	    </Card>
118	  );
