  db.select().from(entities).where(eq(entities.projectId, projectId)),
  db.select().from(rules).where(eq(rules.projectId, projectId)),
  db.select().from(players).where(eq(players.projectId, projectId)),
]);

// Rule depth: average word count per rule rewards detailed, complex rules
const wordCount = (s: string) => s.trim().split(/\s+/).filter(Boolean).length;
const avgRuleWords = rs.length > 0
  ? rs.reduce((sum, r) => sum + wordCount(r.content ?? ""), 0) / rs.length
  : 0;

// Mechanic complexity: penalty points for hard mechanics found in game text
const corpus = [
  project.description ?? "",
  project.gameType ?? "",
  project.genre ?? "",
  ...rs.map((r) => r.content ?? ""),
].join(" ").toLowerCase();
const mechPenalties: Record<string, number> = {
  asymmetric: 5, asymmetry: 5,
  cooperative: 4, "co-op": 4,
  "hidden information": 3, "secret information": 3, "fog of war": 3, hidden: 2,
  simultaneous: 3, "real-time": 3,
  legacy: 4, campaign: 3,
  "deck building": 2, "deck-building": 2,
  "worker placement": 2, "area control": 2,
  "engine building": 2, "hidden role": 3,
};
let mechScore = 0;
for (const [term, pts] of Object.entries(mechPenalties)) {
  if (corpus.includes(term)) mechScore += pts;
}
mechScore = Math.min(15, mechScore);

const breakdown = [
  { factor: "Rule count",    value: Math.min(20, rs.length * 2) },
  { factor: "Rule depth",    value: Math.min(20, Math.floor(avgRuleWords / 5)) },
  { factor: "Hard mechanics",value: mechScore },
